% analyze_grid_density_sensitivity.m
% Full robot-density / grid-size sensitivity analysis for the three DCTA
% missions. The canonical output is the combined analysis table. Historical
% supplementary plots and narrative drafts are disabled for the public
% release; Figure 4 is generated by recompute_grid_density_complete_blocks.m.
%
% Design actually present in the uploaded combined bundles (inferred and
% validated at run time):
%   grid side length:            14, 19, 25, 34
%   nominal cells per robot:     50, 85, 140, 220
%   communication:               ideal, Bernoulli p_d = 0.25
%   algorithms:                  CBAA, ACBBA, PI, HIPC, DMCHBA, DGA
%   attempted trials/condition:  50
%
% Analysis principles:
% 1. Completion probability and efficiency conditional on completion are
%    reported separately. Failed trials are never assigned a step penalty.
% 2. Density levels are paired by trial only within a fixed grid, algorithm,
%    and communication setting because those levels share scenarios.
% 3. Grid sizes use independent-sample tests because each grid has a
%    separately generated scenario set; equal trial_id values across grids
%    are not treated as matched observations.
% 4. Algorithm comparisons are trial-paired within an exact
%    grid/density/communication condition and require all six algorithms to
%    have an eligible continuous-metric value.
% 5. Every pairwise family is Holm-adjusted within its corresponding
%    omnibus family.

clear; clc; close all;

scriptDir = fileparts(mfilename('fullpath'));
repoRoot = fileparts(fileparts(scriptDir));
tableDir = fullfile(scriptDir, 'tables');
figureDir = fullfile(scriptDir, 'figures');
if ~exist(tableDir, 'dir'), mkdir(tableDir); end
if ~exist(figureDir, 'dir'), mkdir(figureDir); end

logFile = fullfile(tableDir, 'grid_density_analysis_validation_log.txt');
if isfile(logFile), delete(logFile); end
diary(logFile);
cleanupDiary = onCleanup(@() diary('off')); %#ok<NASGU>

fprintf('DCTA robot-density / grid-size sensitivity analysis\n');
fprintf('Started: %s\n', char(datetime('now', 'Format', 'yyyy-MM-dd HH:mm:ss Z')));
fprintf('MATLAB: %s\n', version);
fprintf('Repository: repository root\n\n');

missionSpecs = makeMissionSpecs(repoRoot);
metricSummaryParts = cell(1, numel(missionSpecs));
completionSummaryParts = cell(1, numel(missionSpecs));
inputAuditParts = cell(1, numel(missionSpecs));
densityOmnibusParts = cell(1, numel(missionSpecs));
densityPairwiseParts = cell(1, numel(missionSpecs));
gridOmnibusParts = cell(1, numel(missionSpecs));
gridPairwiseParts = cell(1, numel(missionSpecs));
algorithmOmnibusParts = cell(1, numel(missionSpecs));
algorithmPairwiseParts = cell(1, numel(missionSpecs));
completionOmnibusParts = cell(1, numel(missionSpecs));
completionPairwiseParts = cell(1, numel(missionSpecs));
gridElasticityParts = cell(1, numel(missionSpecs));
densityElasticityParts = cell(1, numel(missionSpecs));

sourceManifest = makeSourceManifest(missionSpecs, repoRoot);

for si = 1:numel(missionSpecs)
    spec = missionSpecs(si);
    fprintf('=== %s ===\n', spec.name);
    [T, manifest, audit] = loadAndValidateMission(spec);
    inputAuditParts{si} = audit;

    factors = inferFactors(T);
    assertExpectedActualDesign(factors, spec);
    fprintf('Rows: %d; completed: %d; failed: %d\n', ...
        height(T), sum(T.completed), sum(~T.completed));
    fprintf('Grid sizes: %s\n', joinNumbers(factors.grids));
    fprintf('Nominal cells/robot: %s\n', joinNumbers(factors.densities));
    fprintf('Communication labels: %s\n', strjoin(cellstr(factors.comms), ', '));
    fprintf('Algorithms: %s\n\n', strjoin(cellstr(upper(factors.algorithms)), ', '));

    metricSummary = summarizeMetrics(T, spec, factors);
    completionSummary = summarizeCompletion(T, spec, factors);
    [densityOmnibus, densityPairwise] = densityTests(T, spec, factors);
    [gridOmnibus, gridPairwise] = gridTests(T, spec, factors);
    [algorithmOmnibus, algorithmPairwise] = algorithmTests(T, spec, factors);
    [completionOmnibus, completionPairwise] = completionTests(T, spec, factors);
    gridElasticity = gridScalingElasticity(metricSummary, spec, factors);
    densityElasticity = densityScalingElasticity(metricSummary, spec, factors);

    metricSummaryParts{si} = metricSummary;
    completionSummaryParts{si} = completionSummary;
    densityOmnibusParts{si} = densityOmnibus;
    densityPairwiseParts{si} = densityPairwise;
    gridOmnibusParts{si} = gridOmnibus;
    gridPairwiseParts{si} = gridPairwise;
    algorithmOmnibusParts{si} = algorithmOmnibus;
    algorithmPairwiseParts{si} = algorithmPairwise;
    completionOmnibusParts{si} = completionOmnibus;
    completionPairwiseParts{si} = completionPairwise;
    gridElasticityParts{si} = gridElasticity;
    densityElasticityParts{si} = densityElasticity;
end

metricSummary = vertcat(metricSummaryParts{:});
completionSummary = vertcat(completionSummaryParts{:});
inputAudit = vertcat(inputAuditParts{:});
densityOmnibus = vertcat(densityOmnibusParts{:});
densityPairwise = vertcat(densityPairwiseParts{:});
gridOmnibus = vertcat(gridOmnibusParts{:});
gridPairwise = vertcat(gridPairwiseParts{:});
algorithmOmnibus = vertcat(algorithmOmnibusParts{:});
algorithmPairwise = vertcat(algorithmPairwiseParts{:});
completionOmnibus = vertcat(completionOmnibusParts{:});
completionPairwise = vertcat(completionPairwiseParts{:});
gridElasticity = vertcat(gridElasticityParts{:});
densityElasticity = vertcat(densityElasticityParts{:});

densityFigureSource = makeDensityFigureSource(metricSummary);
gridFigureSource = makeGridFigureSource(metricSummary);
completionFigureSource = makeCompletionFigureSource(completionSummary);

resultNames = ["source_manifest", "input_audit", "metric_summary", ...
    "completion_summary", "density_omnibus", "density_pairwise_tests", ...
    "grid_size_omnibus", "grid_size_pairwise_tests", ...
    "algorithm_omnibus", "algorithm_pairwise_tests", ...
    "completion_omnibus", "completion_pairwise_tests", ...
    "grid_size_elasticity", "robot_density_elasticity", ...
    "figure_robot_density_source", "figure_grid_size_source", ...
    "figure_completion_source"];
resultTables = {sourceManifest, inputAudit, metricSummary, completionSummary, ...
    densityOmnibus, densityPairwise, gridOmnibus, gridPairwise, ...
    algorithmOmnibus, algorithmPairwise, completionOmnibus, ...
    completionPairwise, gridElasticity, densityElasticity, ...
    densityFigureSource, gridFigureSource, completionFigureSource};
combinedResults = combineAnalysisTables(resultNames, resultTables);
writeOutputTable(combinedResults, tableDir, 'grid_density_analysis_results.csv');
removeLegacyAnalysisCsvs(tableDir);

generateHistoricalSupplement = false;
if generateHistoricalSupplement
    makeDensityFigure(densityFigureSource, missionSpecs, figureDir);
    makeGridFigure(gridFigureSource, missionSpecs, figureDir);
    makeCompletionFigure(completionFigureSource, missionSpecs, figureDir);
    captionFile = fullfile(scriptDir, 'GRID_DENSITY_FIGURE_CAPTIONS.tex');
    writeCaptions(captionFile);
    reportFile = fullfile(scriptDir, 'GRID_DENSITY_SENSITIVITY_REPORT.md');
    writeReport(reportFile, missionSpecs, inputAudit, metricSummary, ...
        completionSummary, densityOmnibus, densityPairwise, gridOmnibus, ...
        gridPairwise, algorithmOmnibus, algorithmPairwise, ...
        completionOmnibus, completionPairwise, gridElasticity, densityElasticity);
end

validateOutputs(inputAudit, metricSummary, completionSummary, ...
    densityOmnibus, densityPairwise, gridOmnibus, gridPairwise, ...
    algorithmOmnibus, algorithmPairwise, completionOmnibus, ...
    completionPairwise, densityFigureSource, gridFigureSource, ...
    completionFigureSource, tableDir, figureDir, generateHistoricalSupplement);

fprintf('\nCompleted: %s\n', char(datetime('now', 'Format', 'yyyy-MM-dd HH:mm:ss Z')));
fprintf('Canonical output: results/analysis/tables/grid_density_analysis_results.csv\n');

function specs = makeMissionSpecs(repoRoot)
    specs = struct( ...
        'key', {'clips', 'cv', 'fgs'}, ...
        'name', {'Clue-Informed Probabilistic Search (CLIPS)', ...
                 'Collaborative Visit (CV)', ...
                 'Full Grid Search (FGS)'}, ...
        'shortName', {'CLIPS', 'CV', 'FGS'}, ...
        'inputFile', { ...
            fullfile(repoRoot, 'results', 'sensitivity_clue_search_grid_density_50', 'combined', 'sensitivity_clue_search_grid_density_50_combined_system_performance.csv'), ...
            fullfile(repoRoot, 'results', 'sensitivity_known_target_visit_grid_density_50', 'combined', 'system_performance.csv'), ...
            fullfile(repoRoot, 'results', 'sensitivity_coverage_grid_density_50', 'combined', 'system_performance.csv')}, ...
        'manifestFile', { ...
            fullfile(repoRoot, 'results', 'sensitivity_clue_search_grid_density_50', 'combined', 'sensitivity_clue_search_grid_density_50_combined_condition_manifest.csv'), ...
            fullfile(repoRoot, 'results', 'sensitivity_known_target_visit_grid_density_50', 'combined', 'condition_manifest.csv'), ...
            fullfile(repoRoot, 'results', 'sensitivity_coverage_grid_density_50', 'combined', 'condition_manifest.csv')}, ...
        'failureFile', { ...
            fullfile(repoRoot, 'results', 'sensitivity_clue_search_grid_density_50', 'combined', 'condition_failure_summary.csv'), ...
            fullfile(repoRoot, 'results', 'sensitivity_known_target_visit_grid_density_50', 'combined', 'condition_failure_summary.csv'), ...
            fullfile(repoRoot, 'results', 'sensitivity_coverage_grid_density_50', 'combined', 'condition_failure_summary.csv')}, ...
        'trialFile', { ...
            fullfile(repoRoot, 'results', 'sensitivity_clue_search_grid_density_50', 'combined', 'sensitivity_clue_search_grid_density_50_combined_trial_summary.csv'), ...
            fullfile(repoRoot, 'results', 'sensitivity_known_target_visit_grid_density_50', 'combined', 'trial_summary.csv'), ...
            fullfile(repoRoot, 'results', 'sensitivity_coverage_grid_density_50', 'combined', 'trial_summary.csv')}, ...
        'robotFile', { ...
            fullfile(repoRoot, 'results', 'sensitivity_clue_search_grid_density_50', 'combined', 'sensitivity_clue_search_grid_density_50_combined_robot_performance.csv'), ...
            fullfile(repoRoot, 'results', 'sensitivity_known_target_visit_grid_density_50', 'combined', 'robot_performance.csv'), ...
            fullfile(repoRoot, 'results', 'sensitivity_coverage_grid_density_50', 'combined', 'robot_performance.csv')}, ...
        'targetFile', {'', ...
            fullfile(repoRoot, 'results', 'sensitivity_known_target_visit_grid_density_50', 'combined', 'target_performance.csv'), ''}, ...
        'primaryColumn', {'post_clue_steps_to_find', 'total_team_steps', 'total_team_steps'}, ...
        'maxColumn', {'max_steps_any_robot', 'max_robot_steps', 'max_steps_any_robot'}, ...
        'primaryLabel', {'Post-clue team steps', 'Total team steps', 'Total team steps'}, ...
        'normalizedLabel', {'Post-clue steps / grid cell', 'Team steps / target', 'Team steps / grid cell'});
end

function manifest = makeSourceManifest(specs, repoRoot)
    rows = {};
    for i = 1:numel(specs)
        fileRoles = ["system_performance", "condition_manifest", ...
            "condition_failure_summary", "trial_summary", "robot_performance"];
        paths = string({specs(i).inputFile, specs(i).manifestFile, ...
            specs(i).failureFile, specs(i).trialFile, specs(i).robotFile});
        if strlength(string(specs(i).targetFile)) > 0
            fileRoles(end + 1) = "target_performance"; %#ok<AGROW>
            paths(end + 1) = string(specs(i).targetFile); %#ok<AGROW>
        end
        for j = 1:numel(paths)
            info = dir(paths(j));
            if isempty(info)
                error('Required input is absent: %s', paths(j));
            end
            prefix = string(repoRoot) + filesep;
            assert(startsWith(lower(paths(j)), lower(prefix)), ...
                'Source path is outside the repository: %s', paths(j));
            repositoryPath = replace(extractAfter(paths(j), strlength(prefix)), '\', '/');
            rows{end + 1} = table(string(specs(i).name), fileRoles(j), repositoryPath, ... %#ok<AGROW>
                info.bytes, string(datetime(info.datenum, 'ConvertFrom', 'datenum', ...
                'Format', 'yyyy-MM-dd HH:mm:ss Z')), ...
                'VariableNames', {'mission', 'file_role', 'path', 'bytes', 'last_modified'});
        end
    end
    manifest = vertcat(rows{:});
end

function [T, manifest, audit] = loadAndValidateMission(spec)
    required = string({spec.inputFile, spec.manifestFile, spec.failureFile, ...
        spec.trialFile, spec.robotFile});
    if strlength(string(spec.targetFile)) > 0
        required(end + 1) = string(spec.targetFile); %#ok<AGROW>
    end
    if any(~arrayfun(@isfile, required))
        error('At least one required %s input file is absent.', spec.shortName);
    end

    T = readtable(spec.inputFile, 'TextType', 'string');
    % The CLIPS manifest has a large JSON-like command field whose quoted
    % paths confuse MATLAB's delimiter/header autodetection. The verified
    % condition_failure_summary has the same condition keys and expected
    % trial counts, so it is the authoritative condition index for the
    % analysis. The original manifest remains in the source manifest and
    % its physical row count is checked below.
    manifest = readtable(spec.failureFile, 'TextType', 'string', 'Delimiter', ',');
    failures = manifest;

    requiredColumns = ["trial_id", "grid_size", "grid_cells", ...
        "robot_count", "target_cells_per_robot", "actual_cells_per_robot", ...
        "condition_id", "trial_status", "algorithm_key", "comm_label", ...
        string(spec.primaryColumn), string(spec.maxColumn), ...
        "total_team_steps", "messages_sent_total", ...
        "workload_gini_unique_cells_contributed"];
    missing = setdiff(requiredColumns, string(T.Properties.VariableNames));
    if ~isempty(missing)
        error('%s system table is missing: %s', spec.shortName, strjoin(cellstr(missing), ', '));
    end

    T.trial_id = asDouble(T.trial_id);
    T.grid_size = asDouble(T.grid_size);
    T.grid_cells = asDouble(T.grid_cells);
    T.robot_count = asDouble(T.robot_count);
    T.target_cells_per_robot = asDouble(T.target_cells_per_robot);
    T.actual_cells_per_robot = asDouble(T.actual_cells_per_robot);
    T.algorithm_key = lower(string(T.algorithm_key));
    T.comm_label = lower(string(T.comm_label));
    T.condition_id = string(T.condition_id);
    T.completed = lower(string(T.trial_status)) ~= "failed";
    T.primary_metric = asDouble(T.(spec.primaryColumn));
    T.max_agent_steps = asDouble(T.(spec.maxColumn));
    T.total_team_steps_derived = asDouble(T.total_team_steps);
    T.message_publications_per_team_step = safeDivide( ...
        asDouble(T.messages_sent_total), T.total_team_steps_derived);
    T.workload_gini = asDouble(T.workload_gini_unique_cells_contributed);
    if strcmp(spec.key, 'cv') && ismember('workload_gini_targets_found', T.Properties.VariableNames)
        T.target_workload_gini = asDouble(T.workload_gini_targets_found);
    else
        T.target_workload_gini = nan(height(T), 1);
    end
    if strcmp(spec.key, 'cv')
        if ~ismember('target_count', T.Properties.VariableNames)
            error('CV input lacks target_count required for normalization.');
        end
        T.normalized_primary = safeDivide(T.primary_metric, asDouble(T.target_count));
    else
        T.normalized_primary = safeDivide(T.primary_metric, T.grid_cells);
    end

    if any(T.grid_cells ~= T.grid_size .^ 2)
        error('%s contains grid_cells values inconsistent with grid_size^2.', spec.shortName);
    end
    densityCheck = T.grid_cells ./ T.robot_count;
    if any(abs(densityCheck - T.actual_cells_per_robot) > 1e-5)
        error('%s contains inconsistent actual_cells_per_robot values.', spec.shortName);
    end

    manifest.condition_id = string(manifest.condition_id);
    if ismember('expected_trials', manifest.Properties.VariableNames)
        manifest.expected_trials_numeric = asDouble(manifest.expected_trials);
    else
        error('%s manifest lacks expected_trials.', spec.shortName);
    end
    manifestIds = unique(manifest.condition_id);
    systemIds = unique(T.condition_id);
    missingConditions = setdiff(manifestIds, systemIds);
    extraConditions = setdiff(systemIds, manifestIds);

    [gCondition, conditionNames] = findgroups(T.condition_id);
    conditionRows = splitapply(@numel, T.trial_id, gCondition);
    uniqueTrialRows = splitapply(@(x) numel(unique(x)), T.trial_id, gCondition);
    expectedByCondition = nan(size(conditionRows));
    for ci = 1:numel(conditionNames)
        mrow = manifest(manifest.condition_id == conditionNames(ci), :);
        if height(mrow) == 1
            expectedByCondition(ci) = mrow.expected_trials_numeric;
        end
    end
    badCount = sum(conditionRows ~= expectedByCondition);
    duplicateTrialConditions = sum(uniqueTrialRows ~= conditionRows);

    failureExpected = sum(asDouble(failures.expected_trials));
    failureCompleted = sum(asDouble(failures.completed_trials));
    failureFailed = sum(asDouble(failures.failed_trials));
    systemCompleted = sum(T.completed);
    systemFailed = sum(~T.completed);
    expectedTrials = sum(manifest.expected_trials_numeric);

    manifestPhysicalRows = countCsvRows(spec.manifestFile);
    if expectedTrials ~= height(T) || failureExpected ~= expectedTrials || ...
            failureCompleted ~= systemCompleted || failureFailed ~= systemFailed || ...
            ~isempty(missingConditions) || ~isempty(extraConditions) || ...
            badCount ~= 0 || duplicateTrialConditions ~= 0 || ...
            manifestPhysicalRows ~= height(manifest)
        error('%s input audit failed; see computed audit values.', spec.shortName);
    end

    audit = table(string(spec.name), height(manifest), manifestPhysicalRows, ...
        expectedTrials, height(T), ...
        systemCompleted, systemFailed, numel(missingConditions), ...
        numel(extraConditions), badCount, duplicateTrialConditions, ...
        countCsvRows(spec.trialFile), countCsvRows(spec.robotFile), ...
        countOptionalCsvRows(spec.targetFile), true, ...
        'VariableNames', {'mission', 'manifest_conditions', ...
        'condition_manifest_physical_rows', 'expected_system_rows', ...
        'observed_system_rows', 'completed_trials', 'failed_trials', ...
        'missing_conditions', 'extra_conditions', 'bad_condition_row_counts', ...
        'duplicate_condition_trial_keys', 'trial_summary_rows', ...
        'robot_performance_rows', 'target_performance_rows', 'audit_passed'});
end

function factors = inferFactors(T)
    factors.grids = sort(unique(T.grid_size))';
    factors.densities = sort(unique(T.target_cells_per_robot))';
    preferredComms = ["ideal", "bernoulli_025"];
    actualComms = unique(T.comm_label, 'stable')';
    factors.comms = preferredComms(ismember(preferredComms, actualComms));
    factors.comms = [factors.comms, actualComms(~ismember(actualComms, factors.comms))];
    preferredAlgorithms = ["cbaa", "acbba", "pi", "hipc", "dmchba", "dga"];
    actualAlgorithms = unique(T.algorithm_key, 'stable')';
    factors.algorithms = preferredAlgorithms(ismember(preferredAlgorithms, actualAlgorithms));
    factors.algorithms = [factors.algorithms, ...
        actualAlgorithms(~ismember(actualAlgorithms, factors.algorithms))];
end

function assertExpectedActualDesign(factors, spec)
    if ~isequal(factors.grids, [14 19 25 34]) || ...
            ~isequal(factors.densities, [50 85 140 220]) || ...
            ~isequal(factors.comms, ["ideal" "bernoulli_025"]) || ...
            numel(factors.algorithms) ~= 6
        error('%s uploaded bundle does not match the finalized 4x4x2x6 design.', spec.shortName);
    end
end

function summary = summarizeMetrics(T, spec, factors)
    metricKeys = ["primary_metric", "normalized_primary", "max_agent_steps", ...
        "message_publications_per_team_step", "workload_gini"];
    metricLabels = [string(spec.primaryLabel), string(spec.normalizedLabel), ...
        "Maximum-agent steps", "Message publications / team step", ...
        "Unique-cell contribution Gini"];
    units = ["steps", normalizedUnits(spec), "steps", ...
        "publications/team-step", "Gini"];
    if strcmp(spec.key, 'clips')
        metricKeys(end + 1) = "total_team_steps_derived";
        metricLabels(end + 1) = "Total team steps";
        units(end + 1) = "steps";
    elseif strcmp(spec.key, 'cv')
        metricKeys(end + 1) = "target_workload_gini";
        metricLabels(end + 1) = "Target-completion workload Gini";
        units(end + 1) = "Gini";
    end

    rows = {};
    ri = 0;
    for gi = 1:numel(factors.grids)
        for di = 1:numel(factors.densities)
            for ci = 1:numel(factors.comms)
                for ai = 1:numel(factors.algorithms)
                    mask = T.grid_size == factors.grids(gi) & ...
                        T.target_cells_per_robot == factors.densities(di) & ...
                        T.comm_label == factors.comms(ci) & ...
                        T.algorithm_key == factors.algorithms(ai);
                    G = T(mask, :);
                    if isempty(G)
                        error('Missing exact condition in %s metric summary.', spec.shortName);
                    end
                    for mi = 1:numel(metricKeys)
                        values = G.(metricKeys(mi));
                        eligible = G.completed & isfinite(values);
                        x = values(eligible);
                        [lo, hi] = meanCI(x);
                        ri = ri + 1;
                        rows{ri} = table(string(spec.name), string(spec.shortName), ... %#ok<AGROW>
                            metricKeys(mi), metricLabels(mi), units(mi), ...
                            factors.grids(gi), factors.grids(gi)^2, ...
                            factors.densities(di), mode(G.robot_count), ...
                            mode(G.actual_cells_per_robot), factors.comms(ci), ...
                            factors.algorithms(ai), height(G), sum(G.completed), ...
                            numel(x), height(G) - sum(G.completed), mean(x, 'omitnan'), ...
                            median(x, 'omitnan'), std(x, 0, 'omitnan'), ...
                            percentile(x, 25), percentile(x, 75), lo, hi, ...
                            "conditional on completed trials with finite metric", ...
                            "two-sided 95% Student-t CI for the mean", ...
                            'VariableNames', {'mission', 'mission_short', 'metric_key', ...
                            'metric_label', 'units', 'grid_size', 'grid_cells', ...
                            'target_cells_per_robot', 'robot_count', ...
                            'actual_cells_per_robot', 'comm_label', 'algorithm_key', ...
                            'attempted_n', 'completed_n', 'eligible_n', 'failed_n', ...
                            'mean', 'median', 'sd', 'q1', 'q3', 'ci95_low', ...
                            'ci95_high', 'estimand', 'ci_method'});
                    end
                end
            end
        end
    end
    summary = vertcat(rows{:});
end

function summary = summarizeCompletion(T, spec, factors)
    rows = {};
    ri = 0;
    for gi = 1:numel(factors.grids)
        for di = 1:numel(factors.densities)
            for ci = 1:numel(factors.comms)
                for ai = 1:numel(factors.algorithms)
                    mask = T.grid_size == factors.grids(gi) & ...
                        T.target_cells_per_robot == factors.densities(di) & ...
                        T.comm_label == factors.comms(ci) & ...
                        T.algorithm_key == factors.algorithms(ai);
                    G = T(mask, :);
                    attempted = height(G);
                    completed = sum(G.completed);
                    [lo, hi] = wilsonCI(completed, attempted);
                    ri = ri + 1;
                    rows{ri} = table(string(spec.name), string(spec.shortName), ... %#ok<AGROW>
                        factors.grids(gi), factors.grids(gi)^2, ...
                        factors.densities(di), mode(G.robot_count), ...
                        mode(G.actual_cells_per_robot), factors.comms(ci), ...
                        factors.algorithms(ai), attempted, completed, ...
                        attempted - completed, completed / attempted, lo, hi, ...
                        'VariableNames', {'mission', 'mission_short', 'grid_size', ...
                        'grid_cells', 'target_cells_per_robot', 'robot_count', ...
                        'actual_cells_per_robot', 'comm_label', 'algorithm_key', ...
                        'attempted_n', 'completed_n', 'failed_n', 'completion_rate', ...
                        'completion_ci95_wilson_low', 'completion_ci95_wilson_high'});
                end
            end
        end
    end
    summary = vertcat(rows{:});
end

function [omnibus, pairwise] = densityTests(T, spec, factors)
    omnibusRows = {};
    pairwiseRows = {};
    oi = 0; pi = 0;
    metricKeys = ["primary_metric", "normalized_primary"];
    metricLabels = [string(spec.primaryLabel), string(spec.normalizedLabel)];
    for gi = 1:numel(factors.grids)
        for ci = 1:numel(factors.comms)
            for ai = 1:numel(factors.algorithms)
                baseMask = T.grid_size == factors.grids(gi) & ...
                    T.comm_label == factors.comms(ci) & ...
                    T.algorithm_key == factors.algorithms(ai);
                for mi = 1:numel(metricKeys)
                    G = T(baseMask, :);
                    [X, trialIds] = pairedWide(G, 'target_cells_per_robot', ...
                        factors.densities, metricKeys(mi));
                    [q, p, w] = friedmanManual(X);
                    oi = oi + 1;
                    omnibusRows{oi} = table(string(spec.name), metricKeys(mi), ... %#ok<AGROW>
                        metricLabels(mi), factors.grids(gi), factors.comms(ci), ...
                        factors.algorithms(ai), numel(trialIds), ...
                        50 - numel(trialIds), numel(factors.densities), q, ...
                        numel(factors.densities) - 1, p, w, p < 0.05, ...
                        'VariableNames', {'mission', 'metric_key', 'metric_label', ...
                        'grid_size', 'comm_label', 'algorithm_key', 'paired_n', ...
                        'dropped_incomplete_trial_ids', 'level_count', ...
                        'friedman_chi_square', 'df', 'p_value', 'kendall_w', ...
                        'reject_0_05'});
                    familyRows = pairedComparisons(X, factors.densities, ...
                        "target_cells_per_robot");
                    familyRows = addTestContext(familyRows, spec, metricKeys(mi), ...
                        metricLabels(mi), factors.grids(gi), nan, ...
                        factors.comms(ci), factors.algorithms(ai), numel(trialIds), ...
                        "density_within_grid");
                    pairwiseRows{pi + 1} = familyRows; %#ok<AGROW>
                    pi = pi + 1;
                end
            end
        end
    end
    omnibus = vertcat(omnibusRows{:});
    pairwise = vertcat(pairwiseRows{:});
end

function [omnibus, pairwise] = gridTests(T, spec, factors)
    omnibusRows = {};
    pairwiseRows = {};
    oi = 0; pi = 0;
    metricKeys = ["primary_metric", "normalized_primary"];
    metricLabels = [string(spec.primaryLabel), string(spec.normalizedLabel)];
    for di = 1:numel(factors.densities)
        for ci = 1:numel(factors.comms)
            for ai = 1:numel(factors.algorithms)
                baseMask = T.target_cells_per_robot == factors.densities(di) & ...
                    T.comm_label == factors.comms(ci) & ...
                    T.algorithm_key == factors.algorithms(ai);
                for mi = 1:numel(metricKeys)
                    G = T(baseMask, :);
                    groups = cell(1, numel(factors.grids));
                    for gi = 1:numel(factors.grids)
                        mask = G.grid_size == factors.grids(gi) & G.completed & ...
                            isfinite(G.(metricKeys(mi)));
                        groups{gi} = G.(metricKeys(mi))(mask);
                    end
                    [h, p, epsilon2, totalN] = kruskalWallisManual(groups);
                    oi = oi + 1;
                    omnibusRows{oi} = table(string(spec.name), metricKeys(mi), ... %#ok<AGROW>
                        metricLabels(mi), factors.densities(di), ...
                        factors.comms(ci), factors.algorithms(ai), totalN, ...
                        numel(factors.grids), h, numel(factors.grids) - 1, ...
                        p, epsilon2, p < 0.05, ...
                        "independent scenario sets across grid sizes", ...
                        'VariableNames', {'mission', 'metric_key', 'metric_label', ...
                        'target_cells_per_robot', 'comm_label', 'algorithm_key', ...
                        'eligible_n_total', 'level_count', 'kruskal_wallis_h', ...
                        'df', 'p_value', 'epsilon_squared', 'reject_0_05', ...
                        'independence_note'});
                    familyRows = independentComparisons(groups, factors.grids, "grid_size");
                    familyRows = addTestContext(familyRows, spec, metricKeys(mi), ...
                        metricLabels(mi), nan, factors.densities(di), ...
                        factors.comms(ci), factors.algorithms(ai), totalN, ...
                        "grid_size_independent_samples");
                    pairwiseRows{pi + 1} = familyRows; %#ok<AGROW>
                    pi = pi + 1;
                end
            end
        end
    end
    omnibus = vertcat(omnibusRows{:});
    pairwise = vertcat(pairwiseRows{:});
end

function [omnibus, pairwise] = algorithmTests(T, spec, factors)
    omnibusRows = {};
    pairwiseRows = {};
    oi = 0; pi = 0;
    for gi = 1:numel(factors.grids)
        for di = 1:numel(factors.densities)
            for ci = 1:numel(factors.comms)
                mask = T.grid_size == factors.grids(gi) & ...
                    T.target_cells_per_robot == factors.densities(di) & ...
                    T.comm_label == factors.comms(ci);
                G = T(mask, :);
                [X, trialIds] = pairedWide(G, 'algorithm_key', ...
                    factors.algorithms, "primary_metric");
                [q, p, w] = friedmanManual(X);
                oi = oi + 1;
                omnibusRows{oi} = table(string(spec.name), string(spec.primaryLabel), ... %#ok<AGROW>
                    factors.grids(gi), factors.densities(di), factors.comms(ci), ...
                    numel(trialIds), 50 - numel(trialIds), ...
                    numel(factors.algorithms), q, numel(factors.algorithms) - 1, ...
                    p, w, p < 0.05, ...
                    "six-algorithm paired; conditional on all six completing", ...
                    'VariableNames', {'mission', 'metric_label', 'grid_size', ...
                    'target_cells_per_robot', 'comm_label', 'paired_n', ...
                    'dropped_incomplete_trial_ids', 'algorithm_count', ...
                    'friedman_chi_square', 'df', 'p_value', 'kendall_w', ...
                    'reject_0_05', 'estimand'});
                familyRows = pairedComparisons(X, factors.algorithms, "algorithm_key");
                familyRows = addTestContext(familyRows, spec, "primary_metric", ...
                    string(spec.primaryLabel), factors.grids(gi), ...
                    factors.densities(di), factors.comms(ci), "all", ...
                    numel(trialIds), "algorithm_within_condition");
                pairwiseRows{pi + 1} = familyRows; %#ok<AGROW>
                pi = pi + 1;
            end
        end
    end
    omnibus = vertcat(omnibusRows{:});
    pairwise = vertcat(pairwiseRows{:});
end

function [omnibus, pairwise] = completionTests(T, spec, factors)
    omnibusRows = {};
    pairwiseRows = {};
    oi = 0; pi = 0;
    for gi = 1:numel(factors.grids)
        for di = 1:numel(factors.densities)
            for ci = 1:numel(factors.comms)
                mask = T.grid_size == factors.grids(gi) & ...
                    T.target_cells_per_robot == factors.densities(di) & ...
                    T.comm_label == factors.comms(ci);
                G = T(mask, :);
                [X, trialIds] = completionWide(G, factors.algorithms);
                [q, p] = cochranQ(X);
                oi = oi + 1;
                omnibusRows{oi} = table(string(spec.name), factors.grids(gi), ... %#ok<AGROW>
                    factors.densities(di), factors.comms(ci), numel(trialIds), ...
                    numel(factors.algorithms), q, numel(factors.algorithms) - 1, ...
                    p, p < 0.05, ...
                    'VariableNames', {'mission', 'grid_size', ...
                    'target_cells_per_robot', 'comm_label', 'paired_trial_n', ...
                    'algorithm_count', 'cochran_q', 'df', 'p_value', 'reject_0_05'});
                familyRows = mcnemarComparisons(X, factors.algorithms);
                familyRows.mission = repmat(string(spec.name), height(familyRows), 1);
                familyRows.grid_size = repmat(factors.grids(gi), height(familyRows), 1);
                familyRows.target_cells_per_robot = repmat(factors.densities(di), height(familyRows), 1);
                familyRows.comm_label = repmat(factors.comms(ci), height(familyRows), 1);
                familyRows.paired_trial_n = repmat(numel(trialIds), height(familyRows), 1);
                familyRows = movevars(familyRows, {'mission', 'grid_size', ...
                    'target_cells_per_robot', 'comm_label', 'paired_trial_n'}, 'Before', 1);
                pairwiseRows{pi + 1} = familyRows; %#ok<AGROW>
                pi = pi + 1;
            end
        end
    end
    omnibus = vertcat(omnibusRows{:});
    pairwise = vertcat(pairwiseRows{:});
end

function elasticity = gridScalingElasticity(summary, spec, factors)
    rows = {};
    ri = 0;
    for di = 1:numel(factors.densities)
        for ci = 1:numel(factors.comms)
            for ai = 1:numel(factors.algorithms)
                for metricKey = ["primary_metric", "normalized_primary"]
                    G = summary(summary.metric_key == metricKey & ...
                        summary.target_cells_per_robot == factors.densities(di) & ...
                        summary.comm_label == factors.comms(ci) & ...
                        summary.algorithm_key == factors.algorithms(ai), :);
                    [slope, se, lo, hi, p, r2, n] = logLogFit(G.grid_cells, G.mean);
                    ri = ri + 1;
                    rows{ri} = table(string(spec.name), metricKey, ... %#ok<AGROW>
                        factors.densities(di), factors.comms(ci), ...
                        factors.algorithms(ai), n, slope, se, lo, hi, p, r2, ...
                        "condition-mean log-log fit across independent grid scenario sets", ...
                        'VariableNames', {'mission', 'metric_key', ...
                        'target_cells_per_robot', 'comm_label', 'algorithm_key', ...
                        'grid_level_n', 'elasticity', 'elasticity_se', ...
                        'ci95_low', 'ci95_high', 'p_value', 'r_squared', 'method'});
                end
            end
        end
    end
    elasticity = vertcat(rows{:});
end

function elasticity = densityScalingElasticity(summary, spec, factors)
    rows = {};
    ri = 0;
    for gi = 1:numel(factors.grids)
        for ci = 1:numel(factors.comms)
            for ai = 1:numel(factors.algorithms)
                for metricKey = ["primary_metric", "normalized_primary"]
                    G = summary(summary.metric_key == metricKey & ...
                        summary.grid_size == factors.grids(gi) & ...
                        summary.comm_label == factors.comms(ci) & ...
                        summary.algorithm_key == factors.algorithms(ai), :);
                    [slope, se, lo, hi, p, r2, n] = logLogFit( ...
                        G.actual_cells_per_robot, G.mean);
                    ri = ri + 1;
                    rows{ri} = table(string(spec.name), metricKey, ... %#ok<AGROW>
                        factors.grids(gi), factors.comms(ci), ...
                        factors.algorithms(ai), n, slope, se, lo, hi, p, r2, ...
                        "condition-mean log-log fit; positive means worse with fewer robots", ...
                        'VariableNames', {'mission', 'metric_key', 'grid_size', ...
                        'comm_label', 'algorithm_key', 'density_level_n', ...
                        'elasticity', 'elasticity_se', 'ci95_low', 'ci95_high', ...
                        'p_value', 'r_squared', 'method'});
                end
            end
        end
    end
    elasticity = vertcat(rows{:});
end

function source = makeDensityFigureSource(summary)
    S = summary(summary.metric_key == "normalized_primary", :);
    [g, mission, missionShort, comm, algorithm, density, metricLabel, units] = ...
        findgroups(S.mission, S.mission_short, S.comm_label, S.algorithm_key, ...
        S.target_cells_per_robot, S.metric_label, S.units);
    meanValue = splitapply(@(x) mean(x, 'omitnan'), S.mean, g);
    sdAcrossGrids = splitapply(@(x) std(x, 0, 'omitnan'), S.mean, g);
    nGridConditions = splitapply(@(x) sum(isfinite(x)), S.mean, g);
    eligibleN = splitapply(@sum, S.eligible_n, g);
    ciLow = nan(size(meanValue)); ciHigh = nan(size(meanValue));
    for i = 1:max(g)
        x = S.mean(g == i);
        [ciLow(i), ciHigh(i)] = meanCI(x);
    end
    source = table(mission, missionShort, comm, algorithm, density, ...
        metricLabel, units, meanValue, sdAcrossGrids, nGridConditions, ...
        eligibleN, ciLow, ciHigh, ...
        repmat("unweighted marginal mean across available grid-level condition means", numel(meanValue), 1), ...
        'VariableNames', {'mission', 'mission_short', 'comm_label', ...
        'algorithm_key', 'target_cells_per_robot', 'metric_label', 'units', ...
        'mean_normalized_primary', 'sd_across_grid_condition_means', ...
        'grid_condition_n', 'eligible_trial_n_total', 'ci95_low', 'ci95_high', ...
        'aggregation'});
end

function source = makeGridFigureSource(summary)
    S = summary(summary.metric_key == "normalized_primary", :);
    [g, mission, missionShort, comm, algorithm, gridSize, gridCells, metricLabel, units] = ...
        findgroups(S.mission, S.mission_short, S.comm_label, S.algorithm_key, ...
        S.grid_size, S.grid_cells, S.metric_label, S.units);
    meanValue = splitapply(@(x) mean(x, 'omitnan'), S.mean, g);
    sdAcrossDensities = splitapply(@(x) std(x, 0, 'omitnan'), S.mean, g);
    nDensityConditions = splitapply(@(x) sum(isfinite(x)), S.mean, g);
    eligibleN = splitapply(@sum, S.eligible_n, g);
    ciLow = nan(size(meanValue)); ciHigh = nan(size(meanValue));
    for i = 1:max(g)
        x = S.mean(g == i);
        [ciLow(i), ciHigh(i)] = meanCI(x);
    end
    source = table(mission, missionShort, comm, algorithm, gridSize, gridCells, ...
        metricLabel, units, meanValue, sdAcrossDensities, nDensityConditions, ...
        eligibleN, ciLow, ciHigh, ...
        repmat("unweighted marginal mean across available density-level condition means", numel(meanValue), 1), ...
        'VariableNames', {'mission', 'mission_short', 'comm_label', ...
        'algorithm_key', 'grid_size', 'grid_cells', 'metric_label', 'units', ...
        'mean_normalized_primary', 'sd_across_density_condition_means', ...
        'density_condition_n', 'eligible_trial_n_total', 'ci95_low', ...
        'ci95_high', 'aggregation'});
end

function source = makeCompletionFigureSource(summary)
    [g, mission, missionShort, comm, algorithm, density] = findgroups( ...
        summary.mission, summary.mission_short, summary.comm_label, ...
        summary.algorithm_key, summary.target_cells_per_robot);
    attempted = splitapply(@sum, summary.attempted_n, g);
    completed = splitapply(@sum, summary.completed_n, g);
    failed = attempted - completed;
    rate = completed ./ attempted;
    lo = nan(size(rate)); hi = nan(size(rate));
    for i = 1:numel(rate)
        [lo(i), hi(i)] = wilsonCI(completed(i), attempted(i));
    end
    source = table(mission, missionShort, comm, algorithm, density, attempted, ...
        completed, failed, rate, lo, hi, repmat(4, numel(rate), 1), ...
        'VariableNames', {'mission', 'mission_short', 'comm_label', ...
        'algorithm_key', 'target_cells_per_robot', 'attempted_n', ...
        'completed_n', 'failed_n', 'completion_rate', ...
        'completion_ci95_wilson_low', 'completion_ci95_wilson_high', ...
        'pooled_grid_count'});
end

function makeDensityFigure(source, specs, outDir)
    algorithms = ["cbaa", "acbba", "pi", "hipc", "dmchba", "dga"];
    labels = upper(algorithms);
    comms = ["ideal", "bernoulli_025"];
    colors = lines(numel(algorithms));
    fig = figure('Name', 'Robot-density sensitivity', 'Color', 'w', ...
        'Units', 'inches', 'Position', [1 1 7.16 7.6]);
    layout = tiledlayout(3, 2, 'TileSpacing', 'compact', 'Padding', 'compact');
    axesList = gobjects(3, 2);
    for si = 1:numel(specs)
        for ci = 1:numel(comms)
            ax = nexttile(layout); axesList(si, ci) = ax; hold(ax, 'on');
            for ai = 1:numel(algorithms)
                G = source(source.mission_short == string(specs(si).shortName) & ...
                    source.comm_label == comms(ci) & source.algorithm_key == algorithms(ai), :);
                G = sortrows(G, 'target_cells_per_robot');
                errorbar(ax, G.target_cells_per_robot, G.mean_normalized_primary, ...
                    G.mean_normalized_primary - G.ci95_low, ...
                    G.ci95_high - G.mean_normalized_primary, '-o', ...
                    'Color', colors(ai, :), 'LineWidth', 1.0, 'MarkerSize', 3.2, ...
                    'MarkerFaceColor', 'w', 'CapSize', 2, ...
                    'DisplayName', char(labels(ai)));
            end
            grid(ax, 'on'); box(ax, 'on');
            xticks(ax, [50 85 140 220]); xlim(ax, [45 225]);
            title(ax, sprintf('%s — %s', specs(si).shortName, commDisplay(comms(ci))), ...
                'FontWeight', 'normal');
            if ci == 1, ylabel(ax, specs(si).normalizedLabel); end
            if si == numel(specs), xlabel(ax, 'Nominal cells per robot (larger = fewer robots)'); end
            set(ax, 'FontSize', 7, 'LineWidth', 0.7);
        end
    end
    lgd = legend(axesList(1, 1), 'Orientation', 'horizontal', ...
        'NumColumns', 6, 'Box', 'off', 'FontSize', 6.5);
    lgd.Layout.Tile = 'south';
    title(layout, {'Robot-density sensitivity of normalized primary performance', ...
        'means and 95% t intervals across up to four grid-level condition means; efficiency conditional on completion'}, ...
        'FontWeight', 'normal', 'FontSize', 8);
    exportAll(fig, outDir, 'grid_density_robot_density_sensitivity');
end

