function writeCaptions(path)
    fid = fopen(path, 'w');
    if fid < 0, error('Could not create caption file: %s', path); end
    cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
    fprintf(fid, '%% Generated by analyze_grid_density_sensitivity.m.\n');
    fprintf(fid, '\\begin{figure*}[t]\n  \\centering\n');
    fprintf(fid, '  \\includegraphics[width=\\textwidth]{results/analysis/figures/grid_density_robot_density_sensitivity.pdf}\n');
    fprintf(fid, ['  \\caption{Robot-density sensitivity of normalized primary performance for CLIPS, CV, and FGS under ideal and Bernoulli $p_d=0.25$ communication. ', ...
        'The horizontal axis is nominal cells per robot, so movement to the right means a sparser robot team. ', ...
        'CLIPS and FGS are normalized by grid cells; CV is normalized by ten targets. ', ...
        'Points are unweighted means of up to four available grid-level condition means, intervals are 95\\%% Student-$t$ intervals across the contributing means, and efficiency is conditional on mission completion. Exact contributing-condition counts are recorded in the figure source table.}\n']);
    fprintf(fid, '  \\label{fig:grid-density-robot-density}\n\\end{figure*}\n\n');
    fprintf(fid, '\\begin{figure*}[t]\n  \\centering\n');
    fprintf(fid, '  \\includegraphics[width=\\textwidth]{results/analysis/figures/grid_density_grid_size_scaling.pdf}\n');
    fprintf(fid, ['  \\caption{Grid-size scaling of normalized primary performance. ', ...
        'Points are unweighted means of up to four available nominal-density condition means at each grid size, and intervals are 95\\%% Student-$t$ intervals across the contributing means. ', ...
        'Trial IDs are not paired across grid sizes because each grid uses a separately generated scenario set; inferential grid-size comparisons therefore use Kruskal--Wallis and Holm-adjusted rank-sum tests.}\n']);
    fprintf(fid, '  \\label{fig:grid-density-grid-size}\n\\end{figure*}\n\n');
    fprintf(fid, '\\begin{figure*}[t]\n  \\centering\n');
    fprintf(fid, '  \\includegraphics[width=\\textwidth]{results/analysis/figures/grid_density_completion_rates.pdf}\n');
    fprintf(fid, ['  \\caption{Mission-completion probability in the grid-density sensitivity campaign. ', ...
        'Each point pools 200 attempted trials across four grids at a fixed nominal density, and intervals are 95\\%% Wilson intervals. ', ...
        'Completion is presented separately because continuous efficiency metrics condition on successful completion and failed trials are not assigned artificial step penalties.}\n']);
    fprintf(fid, '  \\label{fig:grid-density-completion}\n\\end{figure*}\n');
end

function writeReport(path, specs, audit, metricSummary, completionSummary, ...
        densityOmnibus, densityPairwise, gridOmnibus, gridPairwise, ...
        algorithmOmnibus, algorithmPairwise, completionOmnibus, ...
        completionPairwise, gridElasticity, densityElasticity)
    fid = fopen(path, 'w');
    if fid < 0, error('Could not create report: %s', path); end
    cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
    fprintf(fid, '# Robot-density / grid-size sensitivity analysis\n\n');
    fprintf(fid, 'Generated entirely by `results/analysis/analyze_grid_density_sensitivity.m`.\n\n');
    fprintf(fid, '## Design and estimands\n\n');
    fprintf(fid, ['The uploaded finalized campaign contains four grid side lengths (14, 19, 25, 34), four nominal robot-density levels ', ...
        '(50, 85, 140, and 220 cells per robot), two communication settings (Ideal and Bernoulli $p_d=0.25$), six algorithms, and 50 attempted trials per exact condition. ', ...
        'This is the analyzed 4 x 4 x 2 x 6 design; the older preparation scripts describe a larger planned matrix that is not present in the uploaded results.\n\n']);
    fprintf(fid, ['Completion probability is analyzed over all attempted trials. Continuous metrics are analyzed only for completed trials with finite values; no failed trial receives a synthetic step penalty. ', ...
        'Robot-density tests pair trial IDs only within a fixed grid because density conditions share a scenario set. Grid-size tests are independent-sample tests because scenarios were generated separately for each grid. ', ...
        'Algorithm comparisons require six-way paired eligible trials within each exact condition.\n\n']);
    fprintf(fid, 'Primary metrics are CLIPS post-clue team steps, CV total team steps, and FGS total team steps. Normalized values are CLIPS/FGS steps per grid cell and CV steps per target.\n\n');

    fprintf(fid, '## Input audit and failures\n\n');
    fprintf(fid, '| Mission | Attempted | Completed | Failed | Failure rate | Audit |\n');
    fprintf(fid, '|---|---:|---:|---:|---:|---|\n');
    for i = 1:height(audit)
        fprintf(fid, '| %s | %d | %d | %d | %.2f%% | %s |\n', ...
            char(shortMission(audit.mission(i))), audit.expected_system_rows(i), ...
            audit.completed_trials(i), audit.failed_trials(i), ...
            100 * audit.failed_trials(i) / audit.expected_system_rows(i), ...
            passText(audit.audit_passed(i)));
    end
    fprintf(fid, '\nAll failures recorded in these bundles are represented by `trial_status=failed`; continuous outcomes for those runs are excluded from conditional-efficiency estimates.\n\n');

    fprintf(fid, '## Overall normalized primary performance\n\n');
    fprintf(fid, ['The following values are unweighted averages of the available grid-by-density condition means for each mission, communication setting, and algorithm (up to 16 per row). ', ...
        'Lower is better; they are descriptive marginal summaries, while exact paired tests remain in the CSV outputs.\n\n']);
    N = metricSummary(metricSummary.metric_key == "normalized_primary", :);
    [g, mission, comm, algorithm] = findgroups(N.mission, N.comm_label, N.algorithm_key);
    avg = splitapply(@mean, N.mean, g);
    overall = table(mission, comm, algorithm, avg);
    fprintf(fid, '| Mission | Communication | Best algorithm | Mean normalized primary metric |\n');
    fprintf(fid, '|---|---|---|---:|\n');
    for si = 1:numel(specs)
        for commValue = ["ideal", "bernoulli_025"]
            G = overall(overall.mission == string(specs(si).name) & overall.comm == commValue, :);
            [value, idx] = min(G.avg);
            fprintf(fid, '| %s | %s | %s | %.4f |\n', specs(si).shortName, ...
                char(commDisplay(commValue)), upper(char(G.algorithm(idx))), value);
        end
    end
    fprintf(fid, '\n');

    fprintf(fid, '## Inferential coverage\n\n');
    fprintf(fid, '| Analysis family | Omnibus families | p<0.05 | Pairwise tests | Holm-supported pairs |\n');
    fprintf(fid, '|---|---:|---:|---:|---:|\n');
    fprintf(fid, '| Density within grid (paired Friedman) | %d | %d | %d | %d |\n', ...
        height(densityOmnibus), sum(densityOmnibus.reject_0_05), height(densityPairwise), sum(densityPairwise.reject_holm_0_05));
    fprintf(fid, '| Grid size at fixed density (independent Kruskal--Wallis) | %d | %d | %d | %d |\n', ...
        height(gridOmnibus), sum(gridOmnibus.reject_0_05), height(gridPairwise), sum(gridPairwise.reject_holm_0_05));
    fprintf(fid, '| Algorithms within exact condition (paired Friedman) | %d | %d | %d | %d |\n', ...
        height(algorithmOmnibus), sum(algorithmOmnibus.reject_0_05), height(algorithmPairwise), sum(algorithmPairwise.reject_holm_0_05));
    fprintf(fid, '| Completion by algorithm (Cochran Q / exact McNemar) | %d | %d | %d | %d |\n\n', ...
        height(completionOmnibus), sum(completionOmnibus.reject_0_05), height(completionPairwise), sum(completionPairwise.reject_holm_0_05));

    fprintf(fid, '## Supported algorithm wins\n\n');
    fprintf(fid, ['A supported win is a Holm-significant paired primary-metric comparison; the algorithm with the lower paired median is credited. ', ...
        'Counts below span all 32 exact grid-by-density-by-communication conditions per mission.\n\n']);
    for si = 1:numel(specs)
        G = algorithmPairwise(algorithmPairwise.mission == string(specs(si).name) & algorithmPairwise.reject_holm_0_05, :);
        wins = zeros(6, 1); algs = ["cbaa", "acbba", "pi", "hipc", "dmchba", "dga"]';
        for j = 1:height(G)
            if G.median_delta_level_b_minus_a(j) > 0
                winner = G.level_a(j);
            elseif G.median_delta_level_b_minus_a(j) < 0
                winner = G.level_b(j);
            else
                continue;
            end
            wins(algs == winner) = wins(algs == winner) + 1;
        end
        [sortedWins, order] = sort(wins, 'descend');
        fprintf(fid, '- **%s:** %s.\n', specs(si).shortName, ...
            char(strjoin(upper(algs(order)) + " " + string(sortedWins), ', ')));
    end
    fprintf(fid, '\n');

    fprintf(fid, '## Scaling elasticities\n\n');
    fprintf(fid, ['Elasticity is the slope of a condition-mean log--log fit. Grid-size elasticity uses grid cells as the predictor at fixed nominal density. ', ...
        'Robot-density elasticity uses actual cells per robot at fixed grid; a positive density elasticity means performance worsens as the team becomes sparser. ', ...
        'Each fit has four condition-mean points and should be interpreted as a compact trend descriptor, not as a substitute for the nonparametric tests.\n\n']);
    for si = 1:numel(specs)
        Gg = gridElasticity(gridElasticity.mission == string(specs(si).name) & gridElasticity.metric_key == "normalized_primary", :);
        Gd = densityElasticity(densityElasticity.mission == string(specs(si).name) & densityElasticity.metric_key == "normalized_primary", :);
        fprintf(fid, '- **%s:** median normalized grid-size elasticity %.3f; median robot-density elasticity %.3f.\n', ...
            specs(si).shortName, median(Gg.elasticity, 'omitnan'), median(Gd.elasticity, 'omitnan'));
    end
    fprintf(fid, '\n');

    worst = sortrows(completionSummary, {'completion_rate', 'failed_n'}, {'ascend', 'descend'});
    fprintf(fid, '## Lowest-completion exact conditions\n\n');
    fprintf(fid, '| Mission | Grid | Cells/robot | Comm. | Algorithm | Completed/attempted | Rate |\n');
    fprintf(fid, '|---|---:|---:|---|---|---:|---:|\n');
    for i = 1:min(12, height(worst))
        fprintf(fid, '| %s | %d | %d | %s | %s | %d/%d | %.1f%% |\n', ...
            char(worst.mission_short(i)), worst.grid_size(i), ...
            worst.target_cells_per_robot(i), char(commDisplay(worst.comm_label(i))), ...
            upper(char(worst.algorithm_key(i))), worst.completed_n(i), ...
            worst.attempted_n(i), 100 * worst.completion_rate(i));
    end
    fprintf(fid, '\n');

    fprintf(fid, '## Generated artifacts\n\n');
    fprintf(fid, '- MATLAB script: `results/analysis/analyze_grid_density_sensitivity.m`\n');
    fprintf(fid, '- Validation log: `results/analysis/tables/grid_density_analysis_validation_log.txt`\n');
    fprintf(fid, '- All source, audit, summary, statistical, elasticity, and figure-source rows: `results/analysis/tables/grid_density_analysis_results.csv`\n');
    fprintf(fid, '- Figures: `results/analysis/figures/grid_density_*.png/.pdf/.fig`\n');
    fprintf(fid, '- Paper-ready captions: `results/analysis/GRID_DENSITY_FIGURE_CAPTIONS.tex`\n\n');
    fprintf(fid, 'The primary scientific reading must remain two-part: completion probability first, followed by efficiency conditional on completion.\n');
end

function validateOutputs(audit, metricSummary, completionSummary, ...
        densityOmnibus, densityPairwise, gridOmnibus, gridPairwise, ...
        algorithmOmnibus, algorithmPairwise, completionOmnibus, ...
        completionPairwise, densityFigureSource, gridFigureSource, ...
        completionFigureSource, tableDir, figureDir, requireHistoricalFigures)
    fprintf('\n=== Validation ===\n');
    assert(all(audit.audit_passed), 'At least one input audit failed.');
    % CLIPS and CV each contribute six metrics per exact condition; FGS
    % contributes five: (192 * 6) + (192 * 6) + (192 * 5) = 3264.
    assert(height(metricSummary) == 3264, 'Unexpected metric-summary row count.');
    assert(height(completionSummary) == 576, 'Unexpected completion-summary row count.');
    assert(height(densityOmnibus) == 288, 'Unexpected density omnibus row count.');
    assert(height(densityPairwise) == 1728, 'Unexpected density pairwise row count.');
    assert(height(gridOmnibus) == 288, 'Unexpected grid omnibus row count.');
    assert(height(gridPairwise) == 1728, 'Unexpected grid pairwise row count.');
    assert(height(algorithmOmnibus) == 96, 'Unexpected algorithm omnibus row count.');
    assert(height(algorithmPairwise) == 1440, 'Unexpected algorithm pairwise row count.');
    assert(height(completionOmnibus) == 96, 'Unexpected completion omnibus row count.');
    assert(height(completionPairwise) == 1440, 'Unexpected completion pairwise row count.');
    assert(height(densityFigureSource) == 144, 'Unexpected density figure source row count.');
    assert(height(gridFigureSource) == 144, 'Unexpected grid figure source row count.');
    assert(height(completionFigureSource) == 144, 'Unexpected completion figure source row count.');
    assert(all(densityPairwise.p_holm >= densityPairwise.p_value | isnan(densityPairwise.p_holm)), ...
        'Density Holm p-values are invalid.');
    assert(all(gridPairwise.p_holm >= gridPairwise.p_value | isnan(gridPairwise.p_holm)), ...
        'Grid Holm p-values are invalid.');
    assert(all(algorithmPairwise.p_holm >= algorithmPairwise.p_value | isnan(algorithmPairwise.p_holm)), ...
        'Algorithm Holm p-values are invalid.');
    assert(all(completionPairwise.p_holm >= completionPairwise.p_value | isnan(completionPairwise.p_holm)), ...
        'Completion Holm p-values are invalid.');

    requiredTables = "grid_density_analysis_results.csv";
    requiredFigures = ["grid_density_robot_density_sensitivity.png", ...
        "grid_density_robot_density_sensitivity.pdf", ...
        "grid_density_robot_density_sensitivity.fig", ...
        "grid_density_grid_size_scaling.png", ...
        "grid_density_grid_size_scaling.pdf", ...
        "grid_density_grid_size_scaling.fig", ...
        "grid_density_completion_rates.png", ...
        "grid_density_completion_rates.pdf", ...
        "grid_density_completion_rates.fig"];
    assert(all(arrayfun(@(x) isfile(fullfile(tableDir, x)), requiredTables)), ...
        'At least one required output table is absent.');
    if requireHistoricalFigures
        assert(all(arrayfun(@(x) isfile(fullfile(figureDir, x)), requiredFigures)), ...
            'At least one requested historical figure is absent.');
    end
    fprintf('PASS: input audits, row counts, Holm adjustments, and output inventory.\n');
end

function [X, trialIds] = pairedWide(G, factorName, levels, metricKey)
    trialIdsAll = sort(unique(G.trial_id(isfinite(G.trial_id))))';
    X = nan(numel(trialIdsAll), numel(levels));
    keep = true(numel(trialIdsAll), 1);
    factor = G.(factorName);
    values = G.(metricKey);
    for ti = 1:numel(trialIdsAll)
        for li = 1:numel(levels)
            if isnumeric(factor)
                mask = G.trial_id == trialIdsAll(ti) & factor == levels(li);
            else
                mask = G.trial_id == trialIdsAll(ti) & string(factor) == string(levels(li));
            end
            idx = find(mask & G.completed & isfinite(values));
            if numel(idx) ~= 1
                keep(ti) = false;
                break;
            end
            X(ti, li) = values(idx);
        end
    end
    X = X(keep, :);
    trialIds = trialIdsAll(keep);
end

function [X, trialIds] = completionWide(G, algorithms)
    trialIds = sort(unique(G.trial_id(isfinite(G.trial_id))))';
    X = false(numel(trialIds), numel(algorithms));
    keep = true(numel(trialIds), 1);
    for ti = 1:numel(trialIds)
        for ai = 1:numel(algorithms)
            idx = find(G.trial_id == trialIds(ti) & G.algorithm_key == algorithms(ai));
            if numel(idx) ~= 1
                keep(ti) = false;
                break;
            end
            X(ti, ai) = G.completed(idx);
        end
    end
    X = X(keep, :);
    trialIds = trialIds(keep);
end

function rows = pairedComparisons(X, levels, factorName)
    k = numel(levels);
    nPairs = nchoosek(k, 2);
    pRaw = nan(nPairs, 1);
    baseRows = cell(nPairs, 1);
    ri = 0;
    for a = 1:k-1
        for b = a+1:k
            ri = ri + 1;
            xa = X(:, a); xb = X(:, b);
            delta = xb - xa;
            if isempty(delta)
                p = nan; rrb = nan;
            elseif all(delta == 0)
                p = 1; rrb = 0;
            else
                p = signrank(xb, xa, 'method', 'approximate');
                rrb = rankBiserial(delta);
            end
            pRaw(ri) = p;
            baseRows{ri} = table(string(levels(a)), string(levels(b)), ...
                mean(delta, 'omitnan'), median(delta, 'omitnan'), ...
                numel(delta), p, rrb, string(factorName), ...
                'VariableNames', {'level_a', 'level_b', ...
                'mean_delta_level_b_minus_a', 'median_delta_level_b_minus_a', ...
                'paired_n', 'p_value', 'rank_biserial_b_minus_a', 'factor'});
        end
    end
    rows = vertcat(baseRows{:});
    rows.p_holm = holmAdjust(pRaw);
    rows.reject_holm_0_05 = rows.p_holm < 0.05;
end

function rows = independentComparisons(groups, levels, factorName)
    k = numel(levels);
    nPairs = nchoosek(k, 2);
    pRaw = nan(nPairs, 1);
    baseRows = cell(nPairs, 1);
    ri = 0;
    for a = 1:k-1
        for b = a+1:k
            ri = ri + 1;
            xa = groups{a}; xb = groups{b};
            if isempty(xa) || isempty(xb)
                p = nan; delta = nan;
            else
                p = ranksum(xb, xa, 'method', 'approximate');
                delta = cliffsDelta(xa, xb);
            end
            pRaw(ri) = p;
            baseRows{ri} = table(string(levels(a)), string(levels(b)), ...
                mean(xb, 'omitnan') - mean(xa, 'omitnan'), ...
                median(xb, 'omitnan') - median(xa, 'omitnan'), ...
                numel(xa), numel(xb), p, delta, string(factorName), ...
                'VariableNames', {'level_a', 'level_b', ...
                'mean_delta_level_b_minus_a', 'median_delta_level_b_minus_a', ...
                'n_a', 'n_b', 'p_value', 'cliffs_delta_b_minus_a', 'factor'});
        end
    end
    rows = vertcat(baseRows{:});
    rows.p_holm = holmAdjust(pRaw);
    rows.reject_holm_0_05 = rows.p_holm < 0.05;
end

function rows = addTestContext(rows, spec, metricKey, metricLabel, gridSize, ...
        density, comm, algorithm, familyN, analysisType)
    n = height(rows);
    rows.mission = repmat(string(spec.name), n, 1);
    rows.metric_key = repmat(string(metricKey), n, 1);
    rows.metric_label = repmat(string(metricLabel), n, 1);
    rows.grid_size = repmat(gridSize, n, 1);
    rows.target_cells_per_robot = repmat(density, n, 1);
    rows.comm_label = repmat(string(comm), n, 1);
    rows.algorithm_key = repmat(string(algorithm), n, 1);
    rows.family_eligible_n = repmat(familyN, n, 1);
    rows.analysis_type = repmat(string(analysisType), n, 1);
    rows = movevars(rows, {'mission', 'metric_key', 'metric_label', ...
        'grid_size', 'target_cells_per_robot', 'comm_label', ...
        'algorithm_key', 'family_eligible_n', 'analysis_type'}, 'Before', 1);
end

function rows = mcnemarComparisons(X, levels)
    k = numel(levels); nPairs = nchoosek(k, 2);
    baseRows = cell(nPairs, 1); pRaw = nan(nPairs, 1); ri = 0;
    for a = 1:k-1
        for b = a+1:k
            ri = ri + 1;
            xa = X(:, a); xb = X(:, b);
            aOnly = sum(xa & ~xb);
            bOnly = sum(~xa & xb);
            discordant = aOnly + bOnly;
            if discordant == 0
                p = 1;
            else
                p = min(1, 2 * binocdf(min(aOnly, bOnly), discordant, 0.5));
            end
            pRaw(ri) = p;
            baseRows{ri} = table(string(levels(a)), string(levels(b)), ...
                sum(xa), sum(xb), aOnly, bOnly, discordant, ...
                mean(xb) - mean(xa), p, ...
                'VariableNames', {'algorithm_a', 'algorithm_b', ...
                'completed_a', 'completed_b', 'a_only_completed', ...
                'b_only_completed', 'discordant_n', ...
                'completion_rate_difference_b_minus_a', 'p_value'});
        end
    end
    rows = vertcat(baseRows{:});
    rows.p_holm = holmAdjust(pRaw);
    rows.reject_holm_0_05 = rows.p_holm < 0.05;
end

function [q, p, w] = friedmanManual(X)
    [n, k] = size(X);
    if n < 2 || k < 2
        q = nan; p = nan; w = nan; return;
    end
    ranks = nan(size(X)); tieSum = 0;
    for i = 1:n
        ranks(i, :) = tiedrank(X(i, :));
        [~, ~, ic] = unique(X(i, :));
        counts = accumarray(ic(:), 1);
        tieSum = tieSum + sum(counts .^ 3 - counts);
    end
    rankSums = sum(ranks, 1);
    q = 12 / (n * k * (k + 1)) * sum(rankSums .^ 2) - 3 * n * (k + 1);
    correction = 1 - tieSum / (n * (k^3 - k));
    if correction <= 0
        q = 0; p = 1; w = 0; return;
    end
    q = q / correction;
    p = chi2Upper(q, k - 1);
    w = q / (n * (k - 1));
end

function [h, p, epsilon2, totalN] = kruskalWallisManual(groups)
    k = numel(groups);
    values = []; labels = [];
    for j = 1:k
        x = groups{j}; x = x(isfinite(x));
        values = [values; x(:)]; %#ok<AGROW>
        labels = [labels; repmat(j, numel(x), 1)]; %#ok<AGROW>
    end
    totalN = numel(values);
    if totalN <= k
        h = nan; p = nan; epsilon2 = nan; return;
    end
    ranks = tiedrank(values);
    h = 0;
    for j = 1:k
        r = ranks(labels == j);
        if isempty(r), h = nan; p = nan; epsilon2 = nan; return; end
        h = h + numel(r) * (mean(r) - (totalN + 1) / 2)^2;
    end
    h = 12 * h / (totalN * (totalN + 1));
    [~, ~, ic] = unique(values);
    counts = accumarray(ic, 1);
    correction = 1 - sum(counts.^3 - counts) / (totalN^3 - totalN);
    if correction > 0, h = h / correction; else, h = 0; end
    p = chi2Upper(h, k - 1);
    epsilon2 = max(0, (h - k + 1) / (totalN - k));
end

function [q, p] = cochranQ(X)
    [n, k] = size(X);
    if n == 0
        q = nan; p = nan; return;
    end
    colTotals = sum(X, 1);
    rowTotals = sum(X, 2);
    denom = k * sum(rowTotals) - sum(rowTotals .^ 2);
    if denom <= 0
        q = 0; p = 1; return;
    end
    q = (k - 1) * (k * sum(colTotals .^ 2) - sum(colTotals)^2) / denom;
    p = chi2Upper(q, k - 1);
end

function p = chi2Upper(x, df)
    p = gammainc(x / 2, df / 2, 'upper');
end

function adjusted = holmAdjust(p)
    adjusted = nan(size(p));
    valid = find(isfinite(p));
    if isempty(valid), return; end
    [sortedP, order] = sort(p(valid));
    m = numel(sortedP);
    scaled = (m - (1:m)' + 1) .* sortedP;
    scaled = cummax(scaled);
    scaled = min(1, scaled);
    sortedIndices = valid(order);
    adjusted(sortedIndices) = scaled;
end

function rrb = rankBiserial(delta)
    delta = delta(isfinite(delta) & delta ~= 0);
    if isempty(delta), rrb = 0; return; end
    ranks = tiedrank(abs(delta));
    wPlus = sum(ranks(delta > 0));
    wMinus = sum(ranks(delta < 0));
    rrb = (wPlus - wMinus) / (wPlus + wMinus);
end

function d = cliffsDelta(a, b)
    a = a(isfinite(a)); b = b(isfinite(b));
    pooled = [a(:); b(:)]; ranks = tiedrank(pooled);
    nb = numel(b); na = numel(a);
    rankB = sum(ranks(na + 1:end));
    uB = rankB - nb * (nb + 1) / 2;
    d = 2 * uB / (na * nb) - 1;
end

function [slope, se, lo, hi, p, r2, n] = logLogFit(x, y)
    valid = isfinite(x) & isfinite(y) & x > 0 & y > 0;
    x = log(double(x(valid))); y = log(double(y(valid))); n = numel(x);
    if n < 3 || numel(unique(x)) < 2
        slope = nan; se = nan; lo = nan; hi = nan; p = nan; r2 = nan; return;
    end
    X = [ones(n, 1), x(:)]; beta = X \ y(:); residual = y(:) - X * beta;
    df = n - 2; s2 = sum(residual .^ 2) / df;
    covariance = s2 * inv(X' * X); %#ok<MINV>
    slope = beta(2); se = sqrt(covariance(2, 2));
    critical = tinv(0.975, df); lo = slope - critical * se; hi = slope + critical * se;
    if se == 0
        p = double(slope == 0);
    else
        p = 2 * tcdf(-abs(slope / se), df);
    end
    total = sum((y - mean(y)).^2);
    if total == 0, r2 = 1; else, r2 = 1 - sum(residual.^2) / total; end
end

function [lo, hi] = meanCI(x)
    x = x(isfinite(x)); n = numel(x);
    if n == 0, lo = nan; hi = nan; return; end
    if n == 1, lo = x; hi = x; return; end
    m = mean(x); half = tinv(0.975, n - 1) * std(x) / sqrt(n);
    lo = m - half; hi = m + half;
end

function [lo, hi] = wilsonCI(successes, n)
    if n <= 0, lo = nan; hi = nan; return; end
    z = 1.95996398454005; p = successes / n; denom = 1 + z^2 / n;
    center = (p + z^2 / (2 * n)) / denom;
    half = z / denom * sqrt(p * (1 - p) / n + z^2 / (4 * n^2));
    lo = max(0, center - half); hi = min(1, center + half);
end

function q = percentile(x, pct)
    x = sort(x(isfinite(x)));
    if isempty(x), q = nan; return; end
    q = prctile(x, pct);
end

function y = safeDivide(a, b)
    y = nan(size(a)); valid = isfinite(a) & isfinite(b) & b ~= 0;
    y(valid) = a(valid) ./ b(valid);
end

function x = asDouble(x)
    if isnumeric(x) || islogical(x)
        x = double(x);
    else
        x = str2double(string(x));
    end
end

function n = countCsvRows(path)
    fid = fopen(path, 'r');
    if fid < 0, error('Could not open CSV for row count: %s', path); end
    cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
    n = -1;
    while ~feof(fid)
        line = fgetl(fid);
        if ischar(line), n = n + 1; end
    end
    n = max(0, n);
end

function n = countOptionalCsvRows(path)
    if strlength(string(path)) == 0, n = 0; else, n = countCsvRows(path); end
end

function combined = combineAnalysisTables(names, tables)
    % Stack heterogeneous analysis tables into one CSV-friendly table. The
    % table_type and source_row columns preserve the original table identity
    % and row ordering; remaining columns are the union of all source fields.
    assert(numel(names) == numel(tables), ...
        'Each combined table requires one table_type name.');
    allVariables = strings(0, 1);
    for i = 1:numel(tables)
        variables = string(tables{i}.Properties.VariableNames(:));
        allVariables = [allVariables; setdiff(variables, allVariables, 'stable')]; %#ok<AGROW>
    end

    parts = cell(numel(tables), 1);
    for i = 1:numel(tables)
        T = tables{i};
        S = table(repmat(names(i), height(T), 1), (1:height(T))', ...
            'VariableNames', {'table_type', 'source_row'});
        sourceVariables = string(T.Properties.VariableNames);
        for vi = 1:numel(allVariables)
            variable = allVariables(vi);
            if any(sourceVariables == variable)
                S.(variable) = csvText(T.(variable));
            else
                missingValues = strings(height(T), 1);
                missingValues(:) = missing;
                S.(variable) = missingValues;
            end
        end
        parts{i} = S;
    end
    combined = vertcat(parts{:});
end

function out = csvText(value)
    if isnumeric(value)
        out = strings(size(value, 1), 1);
        for i = 1:size(value, 1)
            if isscalar(value(i, :))
                out(i) = compose('%.17g', value(i));
            else
                out(i) = strjoin(compose('%.17g', value(i, :)), ';');
            end
        end
    elseif islogical(value)
        out = string(value);
    elseif isdatetime(value) || isduration(value) || iscategorical(value)
        out = string(value);
    elseif iscell(value)
        out = string(value);
    else
        out = string(value);
    end
    out = reshape(out, [], 1);
end

function removeLegacyAnalysisCsvs(tableDir)
    names = [ ...
        "grid_density_analysis_source_manifest.csv", ...
        "grid_density_input_audit.csv", ...
        "grid_density_metric_summary.csv", ...
        "grid_density_completion_summary.csv", ...
        "grid_density_density_omnibus.csv", ...
        "grid_density_density_pairwise_tests.csv", ...
        "grid_density_grid_size_omnibus.csv", ...
        "grid_density_grid_size_pairwise_tests.csv", ...
        "grid_density_algorithm_omnibus.csv", ...
        "grid_density_algorithm_pairwise_tests.csv", ...
        "grid_density_completion_omnibus.csv", ...
        "grid_density_completion_pairwise_tests.csv", ...
        "grid_density_grid_size_elasticity.csv", ...
        "grid_density_robot_density_elasticity.csv", ...
        "figure_grid_density_robot_density_source.csv", ...
        "figure_grid_density_grid_size_source.csv", ...
        "figure_grid_density_completion_source.csv"];
    for i = 1:numel(names)
        path = fullfile(tableDir, names(i));
        if isfile(path), delete(path); end
    end
end

function writeOutputTable(T, outDir, name)
    path = fullfile(outDir, name);
    writetable(T, path);
    fprintf('Wrote %s (%d rows)\n', displayPath(path), height(T));
end

function exportAll(fig, outDir, stem)
    pngPath = fullfile(outDir, stem + ".png");
    pdfPath = fullfile(outDir, stem + ".pdf");
    figPath = fullfile(outDir, stem + ".fig");
    exportgraphics(fig, pngPath, 'Resolution', 600);
    exportgraphics(fig, pdfPath, 'ContentType', 'vector');
    savefig(fig, figPath);
    fprintf('Wrote %s.[png|pdf|fig]\n', displayPath(fullfile(outDir, stem)));
end

function text = displayPath(path)
    normalized = replace(string(path), "\", "/");
    token = regexp(char(normalized), 'results/.*$', 'match', 'once');
    if isempty(token)
        text = normalized;
    else
        text = string(token);
    end
end

function label = commDisplay(comm)
    if string(comm) == "ideal"
        label = "Ideal";
    elseif string(comm) == "bernoulli_025"
        label = "Bernoulli p_d=0.25";
    else
        label = string(comm);
    end
end

function units = normalizedUnits(spec)
    if strcmp(spec.key, 'cv'), units = "steps/target"; else, units = "steps/grid-cell"; end
end

function text = joinNumbers(x)
    text = char(strjoin(string(x), ', '));
end

function short = shortMission(name)
    if contains(name, "CLIPS"), short = "CLIPS";
    elseif contains(name, "Collaborative"), short = "CV";
    else, short = "FGS";
    end
end

function text = passText(value)
    if value, text = 'PASS'; else, text = 'FAIL'; end
end
